class Configplantillanominalcentrocosto extends BaseConfigplantillanominalcentrocosto {
	
/**
     * Obtener la plantilla nominal centro costo dado el identificador.
     * 
     * @param $idestrucesc        			Identificador de la estructura escalar.
     * @return NomEstructuraEscalar    	 	Objeto estructura escalar (clase del dominio).
     */
    public static function obtenerObjConfigplantillanominalcentrocosto($idplantcentrocosto) {
        return Doctrine::getTable('Configplantillanominalcentrocosto')->find($idplantcentrocosto);
    }
	
	public static function obtenerListadoPlantillasNominalesCentroCosto($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->from('Configplantillanominalcentrocosto')
                ->where('idestructura = ?', array($identidad))
                ->fetchArray();
    }
	
	public static function existePlantillaCentroCostoXIdEntidad($idestructura) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        $array = Doctrine_Query::create()
                ->from('Configplantillanominalcentrocosto')
                ->where('idestructura = ?', array($idestructura))
                ->fetchArray();
		if(count($array)>0){
		return "existe";
		}else{
		return "no existe";
		}
    }
    
 }
